/** SA Rent 2 Own logo (icon + wordmark; the "RENT TODAY - OWN TOMORROW"
 * strap line is cropped off), used in the agreement PDF letterhead.
 * Embedded as a data URI rather than read from disk at render time: PDF
 * generation runs inside a Vercel serverless function, and a data URI
 * needs no filesystem/bundling assumptions to work there. Source is the
 * client-provided logo artwork, cropped and resized to 900x236 (same
 * aspect ratio as the original mark).
 */
export const LOGO_DATA_URI =
  "data:image/png;base64,";

export const LOGO_ASPECT_RATIO = 900 / 236;
